import{_ as t,c as o,o as a,ae as l}from"./chunks/framework.Bi6zybwU.js";const u=JSON.parse('{"title":"Manage Cells","description":"Manage Cells","frontmatter":{"title":"Manage Cells","description":"Manage Cells"},"headers":[],"relativePath":"guide/drag-drop-settings/manage-cells-in-ninja-tables-drag-and-drop.md","filePath":"guide/drag-drop-settings/manage-cells-in-ninja-tables-drag-and-drop.md"}'),n={name:"guide/drag-drop-settings/manage-cells-in-ninja-tables-drag-and-drop.md"};function i(s,e,r,h,c,g){return a(),o("div",null,[...e[0]||(e[0]=[l('<h1 id="manage-cells" tabindex="-1">Manage Cells <a class="header-anchor" href="#manage-cells" aria-label="Permalink to &quot;Manage Cells&quot;">​</a></h1><p>Table cells are the central part of data table management. In some cases, we may need to add new rows/columns, duplicate, or delete them as well. In Ninja Tables Drag and Drop mode, select the <strong>Manage Cells</strong> option from the top of the table. This will allow you to make necessary changes to your table cells. <img src="https://ninjatables.com/wp-content/uploads/2023/08/Manage-cells-in-table-1024x762.png" alt="Manage cells in Drag and Drop table"> In this document, you’ll learn how to</p><ul><li>Insert row/column (before and after)</li><li>Duplicate row/column</li><li>Remove row/column</li><li>Merge neighboring cells</li><li>Split merged cells <img src="https://ninjatables.com/wp-content/uploads/2023/08/Manage-table-cells-1024x485.png" alt="Manage table cells"> You can start making changes when you click any of the cells you prefer. To exit this mode simply click on the “Close” button, located below the left sidebar. Let’s get started with managing our Ninja Tables Drag &amp; Drop Table! We’ll explain every option here.</li></ul><h2 id="manage-cells-properties" tabindex="-1">Manage Cells: Properties <a class="header-anchor" href="#manage-cells-properties" aria-label="Permalink to &quot;Manage Cells: Properties&quot;">​</a></h2><p>Let’s find out what each property is designed to do.</p><h3 id="column-highlight-size-merge-split" tabindex="-1">Column Highlight, Size, &amp; Merge/Split <a class="header-anchor" href="#column-highlight-size-merge-split" aria-label="Permalink to &quot;Column Highlight, Size, &amp; Merge/Split&quot;">​</a></h3><p><img src="https://ninjatables.com/wp-content/uploads/2023/08/Select-a-table-cell-to-edit-1024x479.png" alt="Column Highlight, Size, &amp; Merge/Split in Ninja Tables Drag and Drop Table"></p><h4 id="highlight-column" tabindex="-1">Highlight Column <a class="header-anchor" href="#highlight-column" aria-label="Permalink to &quot;Highlight Column&quot;">​</a></h4><p>Highlighting a specific column to make it look different from other columns is a useful feature for pricing tables. Click on the “Highlight Column” from the left. <img src="https://ninjatables.com/wp-content/uploads/2022/10/highlight-table-column-2-1024x573.png" alt="highlight table column in Ninja Tables Drag and drop table"> The available options to highlight a column are:</p><ul><li><strong>Highlight Column Height:</strong> The total height (increased) for the highlighted column.</li><li><strong>Shadow Color:</strong> The color of the shadow for the highlighted column.</li><li><strong>Shadow Effect (X-Axis):</strong> Shift the Shadow along the X-axis.</li><li><strong>Shadow Effect (Y-Axis):</strong> Shift the Shadow along the Y-axis.</li><li><strong>Row Height:</strong> Change the height of the row.</li><li><strong>Column Width:</strong> Change column width.</li><li><strong>Shadow Effect (Blur Radius):</strong> The smoothness or amount of shadow.</li></ul><h4 id="row-height" tabindex="-1">Row Height <a class="header-anchor" href="#row-height" aria-label="Permalink to &quot;Row Height&quot;">​</a></h4><p>With this option, you can either increase the values or manually input the exact value to control the height of the row you select.</p><h4 id="column-width" tabindex="-1">Column Width <a class="header-anchor" href="#column-width" aria-label="Permalink to &quot;Column Width&quot;">​</a></h4><p>With this option, you can control the width of a column by increasing or decreasing the values manually.</p><h4 id="merge-and-split" tabindex="-1">Merge and Split <a class="header-anchor" href="#merge-and-split" aria-label="Permalink to &quot;Merge and Split&quot;">​</a></h4><p>Another important feature of Ninja Tables is to merge neighboring cells in the table. Select a cell and then press <strong>SHIFT</strong>, and select another neighboring cell. Now click on the “Merge” button. <img src="https://ninjatables.com/wp-content/uploads/2023/08/merge-data-table-cells-1024x784.png" alt="merge table cells in Ninja Tables Drag and drop table"></p><p><img src="https://ninjatables.com/wp-content/uploads/2023/08/Split-merged-cells-1024x780.png" alt="Split table cells in Ninja Tables Drag and drop table"> If you want the merged cells to get back to how they were as single separate cells, click the “Split” button.</p><h3 id="table-row-customization" tabindex="-1">Table Row Customization <a class="header-anchor" href="#table-row-customization" aria-label="Permalink to &quot;Table Row Customization&quot;">​</a></h3><p>To customize or to make adjustments to your rows, select a cell and click the <strong>small expandable arrow</strong> on the left. A dropdown will appear with multiple-row customizing options. <img src="https://ninjatables.com/wp-content/uploads/2023/08/customize-and-manage-table-tows-1024x638.png" alt="customize and manage table rows in Ninja Tables Drag and Drop Table"><strong>Insert Row Before:</strong> Choose this, when you want to add another row before your selected row. The newly added row will be empty until you fill it in. <strong>Insert Row After:</strong> Choose this, when you want to add a new blank row after your selected row. <strong>Insert Top Row:</strong> Choose this to add a row at the top of the table. This row can be used as a 2nd header. <strong>Insert Bottom Row:</strong> Choose this to add a row at the bottom of the table. <strong>Duplicate Row:</strong> You may need to duplicate any of your rows. Choose this option to duplicate an existing row. <strong>Remove Row:</strong> To delete a selected row from the table, click on this option.</p><h3 id="column-customization" tabindex="-1">Column Customization <a class="header-anchor" href="#column-customization" aria-label="Permalink to &quot;Column Customization&quot;">​</a></h3><p>Just like the row customization, if you want to make adjustments to your columns, select your preferred cell and click on the <strong>small expandable arrow</strong> at the top. <img src="https://ninjatables.com/wp-content/uploads/2023/08/customize-and-manage-table-column-1024x695.png" alt="manage table column in Ninja Tables Drag and Drop Table"> **Insert Column Before: **Choose this, when you want to add a column before your selected column. The new column will be blank until filled in. **Insert Column After: **Choose this, when you want to add a column after your selected column. **Insert Left Column: **To add a column on the left side of the selected column, use this option. **Insert Right Column: **To add a column on the right side of the selected column, use this option. **Duplicate Column: **Choose this option to duplicate an existing column. **Remove Column: **To delete a selected column from the table, click on this option.</p><h2 id="conclusion" tabindex="-1">Conclusion <a class="header-anchor" href="#conclusion" aria-label="Permalink to &quot;Conclusion&quot;">​</a></h2><p>That’s all for the Manage Cell options and possibilities you can do in the Ninja Tables Drag &amp; Drop table builder. Highlight a column, split/merge cells, or customize rows/columns however you need. Let us know your thoughts and questions in the comment box.</p>',23)])])}const m=t(n,[["render",i]]);export{u as __pageData,m as default};
